// ── Pastilles des tweets MIL : pictogramme selon weapon_type ────────────────────────────────────────
// Un seul endroit pour : (1) normaliser weapon_type en catégorie, (2) dessiner les pictogrammes
// (canvas pour la carte, SVG pour l'UI : chips de filtre, légende...), (3) l'expression MapLibre
// qui choisit l'image du pin.
//
// Les pictogrammes sont définis une seule fois, en chemins SVG sur une grille 24x24.
// Chaque glyphe = liste d'opérations [mode, d] dessinées dans l'ordre :
//   "f" = remplissage blanc, "c" = « découpe » (peinte de la couleur du fond : le trou laisse voir le pin).

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { TbDrone } from "react-icons/tb";

// ── 1. weapon_type -> catégorie ────────────────────────────────────────────────────────────────
// Les ids sont stables ; les regex tolèrent libellés FR/EN, codes (SMALL_ARMS...), accents et casse.
// Ordre = priorité (« missiles antiaériens » -> airdef avant missile).
export const WEAPON_CATEGORIES = ["airdef", "missile", "drone", "explosive", "aircraft", "naval", "armor", "smallarms"];

const PATTERNS = [
    ["airdef", /anti-?aer|air.?defen[sc]e|defen[sc]e aerienne|\bsam\b/],
    ["missile", /missile|roquet|rocket/],
    ["drone", /drone|\buavs?\b|\buas\b|loitering/],
    ["explosive", /explosi|\bied\b|\bbomb|\bmines?\b|grenade/],
    ["aircraft", /aviation|aircraft|avion|helico|fighter|\bjet\b|air.?strike|frappe aerienne|air force/],
    ["naval", /naval|navy|marine|navire|\bship|vessel|sous-?marin|submarine/],
    ["armor", /artiller|blinde|armou?r|\btanks?\b|howitzer|obus|mortier|mortar/],
    ["smallarms", /leger|small.?arms?|firearm|rifle|fusil|pistol|\bgun|sniper|light weapon|arme.? a feu/],
];

const strip = (s) => String(s ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();

// weapon_type peut être une string, un tableau, ou un tableau sérialisé en JSON / séparé par , ; |
const toList = (raw) => {
    if (Array.isArray(raw)) return raw;
    if (typeof raw !== "string" || !raw.trim()) return [];
    const s = raw.trim();
    if (s.startsWith("[")) {
        try { const a = JSON.parse(s); if (Array.isArray(a)) return a; } catch { /* pas du JSON */ }
    }
    return s.split(/[;,|]/);
};

// Plusieurs armes sur un même tweet : on retient la PREMIÈRE reconnue (ordre du tableau).
// Renvoie "none" si rien ne correspond (le pin garde alors sa pastille blanche habituelle).
export const weaponCategory = (raw) => {
    for (const item of toList(raw)) {
        const t = strip(item);
        const hit = PATTERNS.find(([, re]) => re.test(t));
        if (hit) return hit[0];
    }
    return "none";
};

// Ajoute properties.weapon_cat à chaque feature. Copie légère : à appliquer UNIQUEMENT sur la
// donnée envoyée à MapLibre (addSource / setData), pas sur l'état React ni sur l'export GeoJSON.
export const withWeaponCategory = (fc) => {
    if (!fc?.features) return fc;
    return {
        ...fc,
        features: fc.features.map((f) => ({
            ...f,
            properties: { ...f.properties, weapon_cat: weaponCategory(f.properties?.weapon_type) },
        })),
    };
};

// ── 2. Pictogrammes (grille 24x24, centrés sur 12,12) ──────────────────────────────────────────
const circ = (cx, cy, r) => `M${cx - r} ${cy}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0Z`;
const burst = (cx, cy, radii) => {
    const n = radii.length;
    return radii.map((r, i) => {
        const a = (i / n) * Math.PI * 2 - Math.PI / 2;
        return `${i ? "L" : "M"}${(cx + r * Math.cos(a)).toFixed(2)} ${(cy + r * Math.sin(a)).toFixed(2)}`;
    }).join("") + "Z";
};

