// Catégories dessinées avec une icône de react-icons (Tabler, tracés « trait ») au lieu d'un glyphe maison.
//   k  = échelle de l'icône (grille 24) dans la tête du pin ; sw = épaisseur du trait, en unités de la grille.
// Pour tester une autre icône : ajouter une entrée ici (ex. missile: { Icon: TbMissile, k: 1.35, sw: 2 }).
const ICON_GLYPHS = {
    drone: { Icon: TbDrone, k: 1.2, sw: 2 },
};
// Tracés (attributs d) extraits une seule fois du SVG rendu par react-icons.
const iconPathCache = new Map();
const iconPaths = (Icon) => {
    if (!iconPathCache.has(Icon)) {
        const svg = renderToStaticMarkup(createElement(Icon));
        iconPathCache.set(Icon, [...svg.matchAll(/<path\b[^>]*?\sd="([^"]+)"[^>]*>/g)]
            .filter((m) => !/stroke="none"/.test(m[0])) // certains jeux d'icônes ajoutent un cadre invisible
            .map((m) => m[1]));
    }
    return iconPathCache.get(Icon);
};

// Dessine le pictogramme (blanc) autour du point (20, 20), dans un repère où la « tête » fait 16 px de
// rayon. L'appelant (ensurePinImages) translate / met à l'échelle le contexte pour le placer et le
// dimensionner dans la pastille.
// `cutColor` = couleur de remplissage du pin (pour les découpes des glyphes maison).
const GLYPH_SCALE = 1.1; // glyphes maison : 24 unités -> ~26 px dans un repère de rayon 16 px
export const drawWeaponGlyph = (ctx, cat, cutColor) => {
    const icon = ICON_GLYPHS[cat];
    if (icon) {
        ctx.save();
        ctx.translate(20, 20);
        ctx.scale(icon.k, icon.k);
        ctx.translate(-12, -12);
        ctx.lineWidth = icon.sw;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.strokeStyle = "rgba(255,255,255,0.97)";
        for (const d of iconPaths(icon.Icon)) ctx.stroke(new Path2D(d));
        ctx.restore();
        return;
    }
    const g = WEAPON_GLYPHS[cat];
    if (!g) return;
    ctx.save();
    ctx.translate(20, 20);
    ctx.scale(GLYPH_SCALE, GLYPH_SCALE);
    if (g.rot) ctx.rotate((g.rot * Math.PI) / 180);
    ctx.translate(-12, -12);
    for (const [mode, d] of g.ops) {
        ctx.fillStyle = mode === "c" ? cutColor : "rgba(255,255,255,0.95)";
        ctx.fill(new Path2D(d));
    }
    ctx.restore();
};

// Même pictogramme en SVG (chips de filtre, légende, tableau...). Sans `cut`, les découpes sont de
// vrais trous (masque) : l'icône prend la couleur du texte (currentColor).
export const weaponGlyphSVG = (cat, { size = 16, color = "currentColor", cut = null } = {}) => {
    const icon = ICON_GLYPHS[cat];
    if (icon) return renderToStaticMarkup(createElement(icon.Icon, { size, color }));
    const g = WEAPON_GLYPHS[cat];
    if (!g) return "";
    const maskId = `wg-${cat}`;
    const useMask = !cut && g.ops.some(([m]) => m === "c");
    const body = useMask
        ? `<mask id="${maskId}"><rect width="24" height="24" fill="#fff"/>` +
          g.ops.filter(([m]) => m === "c").map(([, d]) => `<path d="${d}" fill="#000"/>`).join("") +
          `</mask><g mask="url(#${maskId})">` +
          g.ops.filter(([m]) => m === "f").map(([, d]) => `<path d="${d}" fill="${color}"/>`).join("") + `</g>`
        : g.ops.map(([m, d]) => `<path d="${d}" fill="${m === "c" ? cut : color}"/>`).join("");
    const rot = g.rot ? ` transform="rotate(${g.rot} 12 12)"` : "";
    return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true"><g${rot}>${body}</g></svg>`;
};

// ── 3. Expression MapLibre : image du pin MIL selon weapon_cat ─────────────────────────────────
// En dessous de `glyphMinZoom`, la pastille reste simple (les pictogrammes sont illisibles à 10 px) ;
// au-delà, l'image « <prefix>-<catégorie> » (catégorie inconnue -> pastille simple).
export const weaponPinIconExpr = (plainId = "badge-mil", prefix = "badge-mil", glyphMinZoom = 4) => {
    const byCat = ["match", ["get", "weapon_cat"]];
    for (const c of WEAPON_CATEGORIES) byCat.push(c, `${prefix}-${c}`);
    byCat.push(plainId);
    return ["step", ["zoom"], plainId, glyphMinZoom, byCat];
};